export function modImageName(itemName: string): string {
  return MOD_IMAGE_NAMES[normalizeModName(itemName)] || ''
}

function normalizeModName(name: string): string {
  return String(name || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/gi, '')
    .toLowerCase()
}
